static struct usb_driver nct6694_usb_driver = {
	.name		= "nct6694",
	.id_table	= nct6694_ids,
	.probe		= nct6694_usb_probe,
	.disconnect	= nct6694_usb_disconnect,
};
module_usb_driver(nct6694_usb_driver);

